// Intrinsic sizes of the 1920 webp files in public/images/projects (generated by scripts/optimize-images.mjs).
export const projectImageSizes: Record<string, { width: number; height: number }> = {
  image00001: { width: 1920, height: 1440 },
  image00002: { width: 1920, height: 1440 },
  image00003: { width: 1920, height: 2560 },
  image00004: { width: 1920, height: 1280 },
  image00005: { width: 1008, height: 756 },
  image00006: { width: 1920, height: 1440 },
  image00007: { width: 1920, height: 1440 },
  image00008: { width: 1920, height: 2560 },
  image00009: { width: 1920, height: 2560 },
  image00010: { width: 1920, height: 1440 },
  image00011: { width: 1920, height: 1440 },
};

// Takes '/images/projects/image00004.webp' and returns responsive attributes.
export function projectImg(src: string) {
  const id = src.match(/(image\d+)\.webp$/)?.[1] ?? '';
  const size = projectImageSizes[id];
  return {
    src,
    srcset: `${src.replace('.webp', '-800.webp')} 800w, ${src} ${size?.width ?? 1920}w`,
    width: size?.width,
    height: size?.height,
  };
}
